#!/usr/bin/env bash
set -euo pipefail
docker_discover() { local out="$1"; if ! command -v docker >/dev/null 2>&1; then echo '{"installed":false}' >"$out"; return; fi; jq -n --argjson containers "$(docker ps -a --format '{{json .}}' | jq -s .)" --argjson networks "$(docker network ls --format '{{json .}}' | jq -s .)" --argjson volumes "$(docker volume ls --format '{{json .}}' | jq -s .)" '{installed:true,containers:$containers,networks:$networks,volumes:$volumes}' >"$out"; }
docker_backup() { local root="$1/docker"; mkdir -p "$root/volumes"; command -v docker >/dev/null 2>&1 || return 0; docker ps -a --format '{{json .}}' | jq -s . >"$root/containers.json"; docker inspect $(docker ps -aq) >"$root/inspect.json" 2>/dev/null || echo '[]' >"$root/inspect.json"; docker volume ls -q | while read -r v; do [[ -n "$v" ]] || continue; docker run --rm -v "$v:/volume:ro" -v "$root/volumes:/backup" alpine sh -c "cd /volume && tar -cf /backup/${v}.tar ." 2>/dev/null || log_warn "Volume backup skipped: $v"; done; find / -name 'docker-compose.yml' -o -name 'compose.yml' 2>/dev/null | tar -T - -cf "$root/compose-files.tar" 2>/dev/null || true; }
docker_restore() { local root="$1/docker"; command -v docker >/dev/null 2>&1 || return 0; [[ -d "$root/volumes" ]] || return 0; for f in "$root"/volumes/*.tar; do [[ -f "$f" ]] || continue; local v; v="$(basename "$f" .tar)"; docker volume create "$v" >/dev/null; docker run --rm -v "$v:/volume" -v "$root/volumes:/backup:ro" alpine sh -c "cd /volume && tar -xf /backup/${v}.tar" || true; done; }
